mapper.select:
        select *
        from project_image_progress
        
            bool_delete_enum = 0
            
                and project_id = #{projectId}
            

            
                and date_format(create_time, '%Y-%m') = #{yearMonth}
            
            
                and date(create_time) = #{date}
            
        
        order by id desc

SELECT project_id, date(create_time ) AS date FROM `project_image_progress` WHERE bool_delete_enum = 0 and project_id = #{projectId}
and date_format(create_time, '%Y-%m') = #{yearMonth}
GROUP BY date(create_time) ORDER BY date desc
